pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address nonOwner, address newOwner) public {
        vm.assume(nonOwner != address(c.owner()));
        vm.prank(nonOwner);
        try c.transferOwnership(newOwner) {
            assertTrue(false);
        } catch {
            assertTrue(true);
        }
    }
}
